import qrcode
import os
import json

# Define a function to generate QR codes for a list of cryptocurrency wallet addresses
def generate_qr_codes(wallet_addresses, output_dir):
    """
    Generate QR codes for the given cryptocurrency wallet addresses.

    Parameters:
    wallet_addresses (dict): A dictionary where keys are cryptocurrency types and values are wallet addresses.
    output_dir (str): The directory where the generated QR code images will be saved.

    Raises:
    ValueError: If the output directory does not exist or is not writable.
    """
    # Check if the output directory exists and is writable
    if not os.path.exists(output_dir):
        raise ValueError(f"The output directory '{output_dir}' does not exist.")
    if not os.access(output_dir, os.W_OK):
        raise ValueError(f"The output directory '{output_dir}' is not writable.")

    # Iterate over the wallet addresses and generate QR codes
    for crypto_type, address in wallet_addresses.items():
        try:
            # Create a QR code instance
            qr = qrcode.QRCode(
                version=1,
                error_correction=qrcode.constants.ERROR_CORRECT_L,
                box_size=10,
                border=4,
            )
            # Add the wallet address to the QR code
            qr.add_data(address)
            qr.make(fit=True)

            # Create an image from the QR Code instance
            img = qr.make_image(fill_color="black", back_color="white")

            # Define the output file path
            output_file = os.path.join(output_dir, f"{crypto_type}_wallet_qr.png")

            # Save the image
            img.save(output_file)
            print(f"QR code for {crypto_type} wallet address saved to: {output_file}")

        except Exception as e:
            print(f"Failed to generate QR code for {crypto_type}: {e}")

